import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

# <<<IMPROVE:helpers>>>
_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p82_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor depthwise_conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding
);

torch::Tensor depthwise_conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding
) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 4, "input must be 4D");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(weight.size(1) == 1, "weight dim 1 must be 1 for depthwise conv");
    TORCH_CHECK(weight.size(2) == weight.size(3), "weight must be square");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    c10::optional<torch::Tensor> bias_c;
    if (bias.has_value() && bias.value().defined()) {
        bias_c = bias.value().contiguous();
    }

    return depthwise_conv2d_forward_cuda(input_c, weight_c, bias_c, stride, padding);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("depthwise_conv2d_forward", &depthwise_conv2d_forward,
          "Depthwise 2D convolution forward (CUDA)",
          py::arg("input"), py::arg("weight"), py::arg("bias"),
          py::arg("stride"), py::arg("padding"));
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int kernel_size, int stride, int padding,
    int total
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    // Decode idx -> (n, c, oh, ow)
    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int c = tmp % C;
    int n = tmp / C;

    float acc = 0.0f;

    for (int kh = 0; kh < kernel_size; kh++) {
        int ih = oh * stride - padding + kh;
        if (ih < 0 || ih >= H_in) continue;
        for (int kw = 0; kw < kernel_size; kw++) {
            int iw = ow * stride - padding + kw;
            if (iw < 0 || iw >= W_in) continue;

            float in_val = input[((n * C + c) * H_in + ih) * W_in + iw];
            float w_val = weight[((c * 1 + 0) * kernel_size + kh) * kernel_size + kw];
            acc += in_val * w_val;
        }
    }

    if (bias != nullptr) {
        acc += bias[c];
    }

    output[((n * C + c) * H_out + oh) * W_out + ow] = acc;
}

torch::Tensor depthwise_conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding
) {
    int N = input.size(0);
    int C = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int kernel_size = weight.size(2);

    int H_out = (H_in + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W_in + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    int total = N * C * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias.value().defined()) {
        bias_ptr = bias.value().data_ptr<float>();
    }

    depthwise_conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H_in, W_in,
        H_out, W_out,
        kernel_size, (int)stride, (int)padding,
        total
    );

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel error: ", cudaGetErrorString(err));

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a depthwise 2D convolution operation with square input and square kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            kernel_size (int): Size of the convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, groups=in_channels, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the depthwise 2D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, in_channels, height_out, width_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        conv = self.conv2d
        if (x.is_cuda and x.is_contiguous() and
                conv.weight.is_cuda and
                x.dim() == 4 and conv.weight.dim() == 4 and
                conv.groups == conv.in_channels and
                conv.out_channels == conv.in_channels and
                conv.weight.size(1) == 1 and
                conv.weight.size(2) == conv.weight.size(3) and
                isinstance(conv.stride, tuple) and conv.stride[0] == conv.stride[1] and
                isinstance(conv.padding, tuple) and conv.padding[0] == conv.padding[1] and
                x.dtype == torch.float32 and conv.weight.dtype == torch.float32):
            bias_tensor = conv.bias.contiguous() if conv.bias is not None else None
            return _stark_get_extension().depthwise_conv2d_forward(
                x,
                conv.weight.contiguous(),
                bias_tensor,
                int(conv.stride[0]),
                int(conv.padding[0])
            )
        return self.conv2d(x)
        # <<<END_IMPROVE>>>
